SELECT stock.STOCK_DATE, stock.MATERIAL_CODE, stock.MES_MATERIAL_CODE, stock.STOCK_NUM, stock.WEEK_YEAR, stock.IS_UNIFORMITY, stock.IS_DYNAMIC_BALANCE, stock.STOCK_END_TIME, stock.DATA_VERSION, stock.COMPANY_CODE, stock.FACTORY_CODE, info.PRODUCT_TYPE_CODE, info.BRAND, info.STRUCTURE_NAME, -- info.LOCATION_TYPE, info.MATERIAL_DESC FROM mes_product_stock stock LEFT JOIN T_MDM_MATERIAL_INFO info ON stock.MATERIAL_CODE = info.MATERIAL_CODE WHERE 1 = 1 AND stock.STOCK_DATE = #{stockDate} AND stock.MATERIAL_CODE like concat(concat('%', #{materialCode}), '%')
AND stock.FACTORY_CODE = #{factoryCode}
AND stock.MATERIAL_CODE IN
